Perfect! QEMU is running and VNC is listening on port 5901. Now let me set up the nginx web interface with noVNC for browser-based access:
[tool_use Bash] cat > /etc/nginx/sites-available/win311-vnc << 'EOF'
server {
    listen 80 default_server;
    server_name _;

    root /usr/share/novnc;
    index vnc.html;

    location / {
        try_files $uri $uri/ =404;
    }

    # Websockify proxy for VNC WebSocket connection
    location /websockify {
        proxy_pass http://localhost:6081;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_read_timeout 86400;
    }

    # CORS headers for WebSocket
    add_header 'Access-Control-Allow-Origin' '*' always;
    add_header 'Access-Control-Allow-Methods' 'GET, POST, OPTIONS' always;
    add_header 'Access-Control-Allow-Headers' 'DNT,User-Agent,X-Requested-With,If-Modified-Since,Cache-Control,Content-Type,Range' always;

    if ($request_method = 'OPTIONS') {
        add_header 'Access-Control-Allow-Origin' '*';
        add_header 'Access-Control-Allow-Methods' 'GET, POST, OPTIONS';
        add_header 'Access-Con ... turn 204;
    }
}
EOF
ln -sf /etc/nginx/sites-available/win311-vnc /etc/nginx/sites-enabled/win311-vnc
rm -f /etc/nginx/sites-enabled/default
nginx -t

